  assert.equal(other.amountMinor, 50);
  const linesBefore = ledger.lines.length;
  const replay = b.refund({ merchantId: 'm_2', chargeId: 'ch_2', amountMinor: 400, idempotencyKey: 'same' });
  assert.deepEqual(replay, other);
  assert.equal(ledger.lines.length, linesBefore);
});

test('merchant scoping does not collide on concatenated ids', () => {
  const list = [
    { id: 'ch_a', merchantId: 'm', amountMinor: 1000, currency: 'USD', plan: 'standard', status: 'captured', capturedAt: 0 },
    { id: 'ch_b', merchantId: 'm:', amountMinor: 1000, currency: 'USD', plan: 'standard', status: 'captured', capturedAt: 0 },
  ];
  const b = new RefundBook(list, new Ledger(), () => 1);
  const one = b.refund({ merchantId: 'm', chargeId: 'ch_a', amountMinor: 10, idempotencyKey: ':k' });
  const two = b.refund({ merchantId: 'm:', chargeId: 'ch_b', amountMinor: 20, idempotencyKey: 'k' });
  assert.notEqual(one.id, two.id);
});

test('returned refunds are copies', () => {
  const b = book();
  const refund = b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k1' });
  refund.amountMinor = 1;
  refund.feeReturnMinor = 999;
  const replay = b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k1' });
  assert.equal(replay.amountMinor, 100);
  assert.equal(replay.feeReturnMinor, 5);
  assert.throws(
    () => b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 901, idempotencyKey: 'k2' }),
    /refund_exceeds_capture/,
  );
});

test('validation and charge checks', () => {
  const list = [
    ...charges(),
    { id: 'ch_p', merchantId: 'm_1', amountMinor: 1000, currency: 'USD', plan: 'standard', status: 'pending', capturedAt: 10 * DAY },
  ];
  const b = new RefundBook(list, new Ledger(), () => 11 * DAY);
  const base = { merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k' };
  for (const bad of [
    { amountMinor: 0 }, { amountMinor: -5 }, { amountMinor: 1.5 }, { amountMinor: '100' },
    { amountMinor: Number.MAX_SAFE_INTEGER + 1 }, { merchantId: '' }, { chargeId: 7 }, { idempotencyKey: '' },
  ]) {
    assert.throws(() => b.refund({ ...base, ...bad }), /invalid_refund/);
  }
  assert.throws(() => b.refund(undefined), /invalid_refund/);
  assert.throws(() => b.refund({ ...base, chargeId: 'nope' }), /charge_not_found/);
  assert.throws(() => b.refund({ ...base, merchantId: 'm_2' }), /charge_not_found/);
  assert.throws(() => b.refund({ ...base, chargeId: 'ch_p' }), /charge_not_captured/);
});

test('refund window: exactly 30 days allowed, later rejected', () => {
  let now = 10 * DAY + 30 * DAY;
  const ledger = new Ledger();
  const b = new RefundBook(charges(), ledger, () => now);
  const ok = b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k1' });
  assert.equal(ok.createdAt, 40 * DAY);
  now += 1;
  assert.throws(
    () => b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k2' }),
    /refund_window_expired/,
  );
  assert.equal(ledger.lines.length, 3);
});

test('refund window: replay still returns the original after the window closes', () => {
  let now = 11 * DAY;
  const b = new RefundBook(charges(), new Ledger(), () => now);
  const original = b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k1' });
  now = 100 * DAY;
  assert.deepEqual(b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 100, idempotencyKey: 'k1' }), original);
});

test('refund window is checked before the capture limit', () => {
  const b = new RefundBook(charges(), new Ledger(), () => 50 * DAY);
  assert.throws(
    () => b.refund({ merchantId: 'm_1', chargeId: 'ch_1', amountMinor: 5000, idempotencyKey: 'k1' }),
    /refund_window_expired/,
  );
});
